import{_ as p}from"./chunks/cc6-2.vmJYoiEs.js";import{_ as r,l as s,o as n,b as c,q as t,d as l,f as e,m as d,j as g}from"./chunks/framework.Tf23FRXt.js";const u="/assets/16826718363712.CewU384h.jpg",m="/assets/151711.B4Y-1xpW.png",_="/assets/seacher.CGedHMxq.jpg",v="/assets/151591.DLkGqwLx.png",h="/assets/finder-config.DnlNKac3.jpg",k="/assets/Trust.DuX_3pme.jpg",f="/assets/recoder.DrLJHQHq.jpg",j=JSON.parse('{"title":"关于副本","description":"","frontmatter":{},"headers":[{"level":2,"title":"副本交流","slug":"副本交流","link":"#副本交流","children":[{"level":3,"title":"遇到很好的队友","slug":"遇到很好的队友","link":"#遇到很好的队友","children":[]},{"level":3,"title":"遇到出状况的队友","slug":"遇到出状况的队友","link":"#遇到出状况的队友","children":[]}]},{"level":2,"title":"随机副本","slug":"随机副本","link":"#随机副本","children":[]},{"level":2,"title":"副本攻略","slug":"副本攻略","link":"#副本攻略","children":[]},{"level":2,"title":"招募队员","slug":"招募队员","link":"#招募队员","children":[]},{"level":2,"title":"排本设置","slug":"排本设置","link":"#排本设置","children":[]},{"level":2,"title":"亲信战友","slug":"亲信战友","link":"#亲信战友","children":[]},{"level":2,"title":"副本录像","slug":"副本录像","link":"#副本录像","children":[]}],"relativePath":"basic/dungeon.htm.md","filePath":"basic/dungeon.md","lastUpdated":1791098838000}'),b={name:"basic/dungeon.htm.md"},x={class:"guide cols2"},T={class:"guide col grow"},w={class:"guide cols2"},S={class:"guide col grow"};function C(P,i,N,q,V,y){const a=s("IncludePage"),o=s("CollapseText");return n(),c("div",null,[i[6]||(i[6]=t('<h1 id="关于副本" tabindex="-1">关于副本</h1><p>副本是 MMORPG 游戏的最大乐趣之一，只要保持礼貌和谦虚的态度，就可以收获非常多快乐。</p><p>在菜单 &gt; 任务情报 &gt; 任务搜索器（默认快捷键 <code>U</code> ）可以打开任务搜索器，勾选自己想要参加的副本并点击下方的<mark>参加</mark> （最多可同时勾选 5 个指定副本），就可以由系统自动匹配其他玩家。</p><blockquote><ul><li><a href="/duty/">副本攻略</a>：如果能在参加副本之前预习一下攻略，是体面的行为。本站收录的副本攻略均无剧透，可放心阅读。</li><li><a href="/topic/battle.htm">挑战副本</a>：如果想要挑战高难度副本，可以阅读这里的介绍了解高难度副本的分类、挑战顺序等建议。</li></ul></blockquote><h2 id="副本交流" tabindex="-1">副本交流</h2><p>在副本中，你会与同副本的玩家组成一个小队，聊天频道会为这个小队形成专用的小队频道，在这个频道里的聊天内容，其他人不会看到。在聊天框里输入 <code>/p</code> ，或者点击输入框前面的小气泡，并选择 “小队”，就可以在小队里发言了。</p><p>默认小队频道的聊天颜色是亮蓝色，如果看到聊天窗口中有亮蓝色的文字，那就是队友在说话了。如果发现队友在跟你说话，你又顾不过来打字，可以在不需要打怪的间隙先打个 <code>==</code> （等于号，意思是等等），然后停下来慢慢打字。（要注意自己的发言频道，如果不是小队频道，那队友是看不到你说话的）</p><div class="guide cols2"><div class="guide col"><img src="'+p+'" width="300px"><p>消息窗口设置 - 人名显示设置</p></div><div class="guide col grow"><p>在输入框下方点击齿轮图标，然后点击<mark>人名显示设置</mark>，可以调整发言者的相关信息设置：</p><ul><li>通用：显示 / 隐藏其他服务器玩家的服务器名</li><li>小队 / 团队：当玩家在小队 / 团队频道发言时，职业 / 职能的显示规则。 <ul><li>可以在下方预览窗口中查看显示效果，推荐显示职业图标 + 整个人名改变颜色。</li></ul></li></ul><p>修改人名显示设置后，就可以更轻松地区分发言者的职业了！</p></div></div><p>FF14 的副本机制较为复杂， 不乏有机制杀的现象。如果是初次进本不熟悉攻略，不妨刚进本就在小队频道打字说一句 “初见，请多关照”，心地善良的老司机通常会愿意一句话讲解。交流是团队合作非常重要的一部分，只要好好交流，很多问题都可以迎刃而解。</p><h3 id="遇到很好的队友" tabindex="-1">遇到很好的队友</h3><div class="guide cols2"><div class="guide col"><img src="'+u+'" width="350px"></div><div class="guide col grow"><p>在打完副本的最后一个 BOSS 之后，屏幕右下角的通知区域会弹出<strong>最优队员推荐</strong>的提示，点击提示，就可以打开推荐最优队员的窗口。</p><p>虽说叫 “最优队员”，其实无论是努力的队员，还是有趣的队员，又或者是友善的队员，都可以为他点赞。</p><p>怀着友好愉快的心情，为你的队友点赞吧～</p></div></div><blockquote><p>进入副本以及最优队员推荐窗口默认显示的是<a href="/topic/plate.htm">玩家肖像</a>，可以在<mark>菜单 &gt; 角色 &gt; 肖像列表</mark>中进行编辑和修改。</p><p>如果不喜欢这个窗口，可以在<mark>角色设置 &gt; 界面设置 &gt; 全体 &gt; 任务用肖像</mark>中进行设置。</p></blockquote><h3 id="遇到出状况的队友" tabindex="-1">遇到出状况的队友</h3><div class="guide cols2"><div class="guide col"><p><img src="'+m+'" alt="" loading="lazy"></p></div><div class="guide col grow"><p>如果你的队友站在原地发呆迟迟不动，在小队频道怎么也叫不到，又或者他掉线之后再也没回来，或者他出口成脏，让人气愤，遇到这些情况都可以使用驱逐队友功能。</p><p>按 <code>O</code> （或菜单 &gt; 小队 &gt; 小队队员）可以打开当前小队的队员列表，在你想要驱逐的玩家上右键 “投票驱逐”，就可以在 “离开”、“离线”、“不良行为” 和 “作弊行为” 中选择一项，并发起驱逐投票。</p><p>这时队伍中的其他玩家会收到投票窗口，如果有超过半数的玩家同意驱逐，那么被投票的玩家就会被强制驱离该副本。</p><p>同一玩家不可连续发起驱逐投票，所以要慎重行事哦。如果遇到严重的情况，可以通过<a href="https://actff1.web.sdo.com/project/20210621ffviolation/index.html#/index" target="_blank" rel="noreferrer">这个平台</a>向游戏运营发起举报，经过运营核实，会给予违规玩家相应的惩罚。</p></div></div><h2 id="随机副本" tabindex="-1">随机副本</h2>',15)),l("div",x,[i[1]||(i[1]=l("div",{class:"guide col"},[l("img",{src:_,width:"350px"}),l("p",null,[e("任务右侧的职能图标表示当前的稀缺职能，"),l("br"),e("使用这个职能排本可以获得额外的奖励。"),l("br"),e("奖励内容显示在右侧报酬奖励的第二行。")])],-1)),l("div",T,[i[0]||(i[0]=t("<p>菜单 &gt; 任务情报 &gt; 任务搜索器（默认快捷键 <code>U</code> ）可以打开任务搜索器，搜索器第一页的随机任务推荐每天都打一次，每日随机会给大量经验。</p><p>如果没多少时间打随机，推荐优先打<mark>练级</mark>和<mark>讨伐</mark>，<mark>团队任务</mark>也可以选择，<mark>主线任务</mark>耗时较长（有不可跳过的任务动画），但奖励也较多，如果有时间推荐打。</p><p>如果不打每日随机的话，会比较容易出现等级跟不上主线要求的情况。</p>",3)),d(a,{file:"_includes/basic/daily.md"})])]),i[7]||(i[7]=t('<h2 id="副本攻略" tabindex="-1">副本攻略</h2><p>FF14 的副本会随着等级的提升有明显的变化，逐渐增加的机制让副本充满变化，我们准备了没有剧透的简易文字攻略，如果遇到问题可以及时查看。</p><p><a href="/duty/">副本攻略</a>，另外也推荐<a href="https://www.bilibili.com/video/av17541239/" target="_blank" rel="noreferrer">副本机制综合介绍视频 (大约 15 分钟)</a>。</p><h2 id="招募队员" tabindex="-1">招募队员</h2><div class="guide cols2"><div class="guide col"><p><img src="'+v+'" alt="" loading="lazy"></p></div><div class="guide col grow"><p>在菜单 &gt; 小队 &gt; 队员招募中可以打开招募板，国服玩家大都通过招募板进行高难度副本或其他游戏内容的组队。</p><p>未开放的内容会显示为<ins>未开放任务</ins>，新人玩家可以在招募板上<strong>吃宝宝</strong> (不知道吃宝宝什么意思？<a href="/advanced/glossary.htm">点我学黑话</a>，通常非当前版本的 Raid 副本也会通过招募 +<a href="#副本解除限制"> 解除限制</a>的方式进行速刷。</p><p>当然招募板上还会有固定队组队的招募、RP 店的广告、商人出售装备的广告等等（如果看到有买卖金、买卖房的广告请不要相信，顺手点一波举报维护游戏环境哦～<a href="https://actff1.web.sdo.com/project/20210621ffviolation/index.html#/index" target="_blank" rel="noreferrer"> 违规处理平台</a>）。</p></div></div><h2 id="排本设置" tabindex="-1">排本设置</h2><div class="guide cols2"><div class="guide col"><p><img src="'+h+'" alt="" loading="lazy"></p></div><div class="guide col grow"><p>在任务搜索器左上角有一个小齿轮，点开后可以打开排本设置。</p><ul><li>中途参战：可以加入正在补充队员的副本任务中。</li><li>解除人数限制（俗称解限）：可以以任意人数参与副本任务，不会发生等级、装备品级同步。（解限后无法获得经验值，也无法获得怪物掉落物，但是可以获得关底宝箱）。</li><li>等级同步：令副本的等级同步生效。</li><li>最低品级：将等级和装备品级同步到副本的最低要求。</li><li>超越之力无效化：不可获得超越之力。</li><li>自由探索：副本内将不会出现怪物，玩家可以在副本内骑乘坐骑、切换职业，自由移动。并且可以在副本内放置木桩，自由使用极限技。（主要用来拍照）。</li><li>分配方式：可以将战利品的分配方式改为仅限贪婪或队长分配。</li><li>限制 “随机任务：练级” 的随机目标：队长打开后，当组满 4 个人参加随机练级任务时，副本等级不会比队伍内等级最低的角色等级低超过 8 级。</li></ul><p>设置的更多信息可以在游戏内查看。</p></div></div><h2 id="亲信战友" tabindex="-1">亲信战友</h2><div class="guide cols2"><div class="guide col"><p><img src="'+k+'" alt="" loading="lazy"></p></div><div class="guide col grow"><p>71 级之后的副本，可以使用亲信战友系统进行反复攻略。</p><p>在<mark>菜单 &gt; 任务情报 &gt; 亲信战友</mark>中可以打开亲信战友菜单。在亲信战友中，使用名为 “幻体” 的主线剧情中的伙伴 NPC，他们具有初始等级，通关副本后，玩家和幻体都可以获得经验值。<strong>和幻体挑战副本时，通关所获得的奖励会少于与其他玩家通关副本时获得的奖励。</strong></p><p>幻体 80 级后会开放<mark>投影</mark>功能，解锁幻体 NPC 的不同外观。同时为幻体升级还可以获得成就、称号。</p></div></div><blockquote><p>没有等级限制，可以随时挑战副本的系统为<a href="/basic/battle.htm#副本迷宫">剧情辅助器</a>。</p></blockquote><h2 id="副本录像" tabindex="-1">副本录像</h2><p>FF14 为部分高难度副本提供 “录像” 功能。每个版本可供 “录像” 的副本任务都不相同，版本更新之后，以往的录像可能会无法播放。</p><p>首先需要在<mark>菜单 &gt; 任务情报 &gt; 任务回顾</mark>中启用任务记录设置，接下来在进入可录像的副本之后，需要在 5 分钟内进行 “记录准备确认”。</p><p>当小队队员全部同意后，会进行战斗倒计时并开始记录。接下来团灭了的话，也推荐使用战斗倒计时功能来进行倒计时（这样录像会自动分段）。</p><p>录像记录最多保存 3 场（以进入副本任务，并全员确认记录准备开始，到退出副本任务为一场），新的录像会自动覆盖最早的录像。</p>',15)),l("div",w,[i[5]||(i[5]=l("div",{class:"guide col"},[l("img",{src:f,width:"350px"})],-1)),l("div",S,[i[3]||(i[3]=l("p",null,[e("录像过的副本，可以在主城的旅馆里进行回放。进入旅馆后，打开"),l("mark",null,"菜单 > 任务情报 > 任务回顾"),e("窗口，就可以看到录像记录。")],-1)),i[4]||(i[4]=l("p",null,"在回放的过程中，玩家可以选择自己、队友，甚至 BOSS 为主视角，欣赏自己的英姿，或观察队友的走位，或者看看出糗搞笑的瞬间。",-1)),d(o,{summary:"播放器按钮说明"},{default:g(()=>[...i[2]||(i[2]=[l("p",null,[e("（1）播放／暂停（2）播放速度：1 倍速（3）播放速度：2 倍速（4）播放速度：4 倍速（5）设置 / 解除焦点目标（6）显示 / 隐藏 HUD"),l("br"),e(" （7）显示帮助（8）启动集体姿势（9）启动景观摄像（10）下一章（11）上一章（12）选择章节（13）回顾播放中的图标（14）回顾结束")],-1)])]),_:1})])])])}const I=r(b,[["render",C]]);export{j as __pageData,I as default};
